<script setup>
import { ArrowDown, ArrowUp, ArrowUpRight, Check, Clapperboard, Copy, Download, FolderOpen, Plus, Redo2, Save, Trash2, Undo2, Upload } from 'lucide-vue-next'
import { MODEL_OPTIONS } from '~/utils/prompt-engine.js'
import { joinAppPath } from '~/utils/urls.js'
import { STUDIO_INSPIRATIONS, promptImageSrc } from '~/utils/reference-content.js'
import { combinedShotPrompts } from '~/utils/open-targets.js'
const store = useProjectStore()
const project = computed(() => store.project.value)
const { notify, copyText, downloadText } = useNotifier()
const boardSearch = ref('')
const editingShotId = ref(null)
const importInput = ref(null)
const activeShot = computed(() => project.value.shots.find(shot=>shot.id===editingShotId.value) || null)
const filteredShots = computed(() => { const query=boardSearch.value.trim().toLowerCase();return project.value.shots.filter(shot=>!query || [shot.title,shot.stage,shot.action,shot.prompt].some(value=>value?.toLowerCase().includes(query))) })
const shotFields = [['title','Title','input'],['action','Action','textarea'],['framing','Framing','input'],['lens','Lens','input'],['camera','Camera movement','input'],['lighting','Lighting','input'],['sound','Sound','input'],['continuity','Continuity','textarea'],['prompt','Complete prompt','textarea']]
function editShot(id) { editingShotId.value=id }
function updateShotField(field,value) { if(activeShot.value)store.updateShotFields(activeShot.value.id,{[field]:value}) }
function onDragStart(event,id) { event.dataTransfer?.setData('text/plain',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move' }
function moveTo(event,id) { const from=event.dataTransfer?.getData('text/plain');const start=project.value.shots.findIndex(shot=>shot.id===from);const end=project.value.shots.findIndex(shot=>shot.id===id);if(start<0||end<0||start===end)return;const next=JSON.parse(JSON.stringify(project.value));const [shot]=next.shots.splice(start,1);next.shots.splice(end,0,shot);next.shots.forEach((item,index)=>item.order=index+1);store.commit(next,'Shot order saved. Undo is available.') }
function exportJson() { try { downloadText(`${(project.value.title||'moovicut').replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.json`,store.serialized) } catch(error) { notify(error.message||'Could not export this project.','error') } }
function openImport() { importInput.value?.click() }
function importProject() { openImport() }
async function importJson(event) { const file=event.target.files?.[0];try { if(!file)return;store.importProject(await file.text()) } catch(error) { notify(error.message||'Could not read this JSON file.','error') } finally { if(event.target)event.target.value='' } }
</script>
<template>
 <div class="studio-editor-content">
  <header class="studio-editor-heading"><div><h3>{{project.title}}</h3><p>Local project · {{project.shots.length}} shots · {{store.duration}} seconds</p></div><div class="editor-toolbar"><button class="icon-button" type="button" title="Undo" aria-label="Undo" :disabled="!store.canUndo" @click="store.undo()"><Undo2 :size="16" /></button><button class="icon-button" type="button" title="Redo" aria-label="Redo" :disabled="!store.future.length" @click="store.redo()"><Redo2 :size="16" /></button><button class="button button-secondary" type="button" @click="store.persist()"><Save :size="14" />Save</button><button class="button button-secondary" type="button" @click="exportJson"><Download :size="14" />Export</button><button class="button button-secondary" type="button" @click="importProject"><Upload :size="14" />Import</button></div></header>
  <div class="studio-tool-grid"><label for="editor-title">Project title<input id="editor-title" :value="project.title" @change="store.commit({...project,title:$event.target.value},'Project title saved')" /></label><label for="editor-model">Prompt model<select id="editor-model" :value="project.model" @change="store.selectModel($event.target.value)"><option v-for="option in MODEL_OPTIONS" :key="option.id" :value="option.id">{{option.label}}</option></select></label><label for="editor-search">Search shots<input id="editor-search" v-model="boardSearch" type="search" placeholder="Search your storyboard" /></label><button class="button button-secondary" type="button" @click="store.addShotAtEnd"><Plus :size="14" />Add shot</button></div>
  <section class="storyboard-section" aria-labelledby="editor-storyboard-heading"><div class="studio-section-header"><div><h4 id="editor-storyboard-heading">Storyboard</h4><p>Edit each shot, copy prompts or drag to reorder.</p></div><span>{{filteredShots.length}} visible shots</span></div><div class="studio-generated-grid" aria-label="Storyboard reference images"><picture v-for="(shot,index) in project.shots.slice(0,9)" :key="shot.id"><source :srcset="joinAppPath(useRuntimeConfig().app.baseURL,promptImageSrc(STUDIO_INSPIRATIONS[index%STUDIO_INSPIRATIONS.length].file,'webp'))" type="image/webp" /><img :src="joinAppPath(useRuntimeConfig().app.baseURL,promptImageSrc(STUDIO_INSPIRATIONS[index%STUDIO_INSPIRATIONS.length].file,'jpg'))" :alt="`${shot.title} storyboard study`" width="1280" height="720" loading="lazy" decoding="async" /></picture></div><OpenInButtons :prompt="combinedShotPrompts(project)" :seed="1" /><div class="shot-board"><ShotCard v-for="(shot,index) in filteredShots" :key="shot.id" :shot="shot" :index="index" :count="filteredShots.length" :model="project.model" @move="direction=>store.moveShot(shot.id,direction)" @delete="store.removeShot(shot.id)" @add="store.insertShot(shot.id)" @copy="copyText(shot.prompt,'Shot prompt copied')" @update-title="title=>store.updateShotFields(shot.id,{title})" @edit="editShot(shot.id)" @dragshot="onDragStart" @move-to="moveTo" /></div><p v-if="!filteredShots.length" class="empty-state">No shots match your search.</p></section>
  <section v-if="activeShot" class="studio-shot-detail" aria-labelledby="shot-detail-heading"><div class="studio-section-header"><div><h4 id="shot-detail-heading">Edit {{activeShot.title}}</h4><p>Changes save locally and can be undone.</p></div><button class="text-button" type="button" @click="editingShotId=null">Close shot</button></div><div class="studio-direct-fields"><label v-for="[field,label,type] in shotFields" :key="field">{{label}}<textarea v-if="type==='textarea'" :value="activeShot[field]" @change="updateShotField(field,$event.target.value)"></textarea><input v-else :value="activeShot[field]" @change="updateShotField(field,$event.target.value)" /></label><label>Duration (seconds)<input type="number" min="2" max="15" :value="activeShot.duration" @change="updateShotField('duration',Number($event.target.value))" /></label></div><p v-if="activeShot.promptEdited" class="studio-edited-mark">Edited by you</p><button class="text-button" type="button" @click="store.regenerateOne(activeShot.id)">Regenerate this shot</button><button v-if="activeShot.promptEdited" class="text-button" type="button" @click="store.resetShotPrompt(activeShot.id)">Reset</button><button class="text-link" type="button" @click="copyText(activeShot.prompt,'Complete prompt copied')"><Copy :size="14" />Copy complete prompt</button></section>
  <section class="studio-local-library" aria-labelledby="local-library-heading"><h4 id="local-library-heading">Saved local projects</h4><ul class="library-list"><li v-for="project in store.savedProjects" :key="project.id"><button type="button" @click="store.loadProject(project);editingShotId=null"><strong>{{project.title}}</strong><span>{{project.shots.length}} shots · {{project.updatedAt?.slice(0,10)}}</span></button><button type="button" class="text-link" :aria-label="`Delete saved project ${project.title}`" @click="store.removeSavedProject(project.id)"><Trash2 :size="13" />Delete</button></li></ul><p v-if="!store.savedProjects.length" class="empty-state">No saved projects yet. Save this storyboard to keep it in this browser.</p></section>
  <p class="form-note">Local planning and source/JSON exports only. External providers handle their own accounts and rendering charges.</p>
  <input ref="importInput" class="sr-only" type="file" accept=".json,application/json" aria-label="Import Moovicut project" @change="importJson" />
 </div>
</template>
